        <rect x={u(compact ? 7 : 14)} y={u(compact ? 7 : 14)} width={SW - u(compact ? 14 : 28)} height={SH - u(compact ? 14 : 28)} style={{ ...thin, strokeWidth: 1 }} {...draw(eOut(seg(0, 0.2)))} />

