            <path d={o === 'h' ? lineD(x, y, x, y + ht) + ' ' + lineD(x + wd, y, x + wd, y + ht) : lineD(x, y, x + wd, y) + ' ' + lineD(x, y + ht, x + wd, y + ht)} style={wallStroke} opacity={cutP} />
            <path d={rectD(x, y, wd, ht)} style={thin} {...draw(winP)} />
