              : <path d={lineD(x + wd * 0.4, y, x + wd * 0.4, y + ht) + ' ' + lineD(x + wd * 0.6, y, x + wd * 0.6, y + ht)} style={thin} {...draw(eOut(seg(0.44 + k * 0.02, 0.58 + k * 0.02)))} />}
