      )}

      {images.map((src, i) => {
        const b = baseFor(i);
        const pos = posOf[i] ?? i;
        const isTop = pos === 0 && !fanned;
        const lifted = dragging === i || (fanned && hoverFan === i);
        const depth = Math.min(pos, 6);
