      if (p < P - 1) {
        for (let q = 1; q < 3; q++) {
          const t = q / 3;
          rungs.push({ a: p * step + t * step, y: (p + t - (P - 1) / 2) * pitch, main: false, k: `s${p}-${q}` });
        }
      }
    }
  }

