        <div style={{ position: 'absolute', left: cx, top: cy, width: 0, height: 0, transformStyle: 'preserve-3d', transform: `rotateZ(${tiltDeg[0] * (compact ? 0.5 : 1)}deg) rotateX(${tiltDeg[1]}deg)` }}>
