          </div>
        </div>
      )}

      {detail && detailT && (
        <div role="dialog" aria-modal="true" aria-label={cap(detail.k) || `Image ${detailT.i + 1}`} style={{ position: 'absolute', inset: 0, zIndex: 20 }}>
