  };
  const scatterLayout = (count, aspect) => {
    const rows = Math.max(2, Math.ceil(Math.sqrt(count / Math.max(0.3, aspect))));
    const cols = Math.max(2, Math.ceil(count / rows));
    const realRows = Math.ceil(count / cols);
