  const [tidy, setTidy] = React.useState(false);
  const [marksOn, setMarksOn] = React.useState(showMarksInit);
  const parseMarks = () => new Set(markedRaw.split(',').map((s) => parseInt(s, 10) - 1).filter((k) => k >= 0));
