      } else if (focusIdx >= 0) {
        const i = focusIdx;
        if (tidy) {
          setPos(images.map((_, q) => { const g = geo(q); return { x: g.cx / surf.w, y: g.cy / surf.h, r: (rnd(q, 3) - 0.5) * 2 * rotAmt * 0.4 }; }));
          setTidy(false);
        }
