        setPos((ps) => ps.map((q, j) => (j === i ? { ...q, x: Math.min(1, Math.max(0, q.x + (arrows[k][0] * step) / surf.w)), y: Math.min(1, Math.max(0, q.y + (arrows[k][1] * step) / surf.h)) } : q)));
