        </div>

        <div style={{ position: 'absolute', top: compact ? 20 : 40, left: compact ? 20 : 48, zIndex: 3, fontFamily: mono, fontSize: 11, letterSpacing: '0.18em', textTransform: 'uppercase', color: muted }}>
