            <div>Z −{String(depthReadout).padStart(5, '0')}</div>
            <div style={{ marginTop: 6, color: textColor }}>{String(Math.min(count, visibleCount)).padStart(2, '0')} / {String(count).padStart(2, '0')}</div>
