  const headlines = React.useMemo(() => String(headRaw).split(/\n|;;/).map((s) => s.trim().toUpperCase()).filter(Boolean), [headRaw]);
  const headCols = compact ? Math.min(headColsCfg, 11) : headColsCfg;

